describe('Login Page Mobile View', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display login form correctly on mobile viewport', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('contain', 'Log In');
    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="logo"]').should('be.visible');
    cy.get('[data-testid="logo"]').should('contain', 'App Name');
  });

  it('should handle mobile keyboard and form submission gracefully', () => {
    cy.viewport('iphone-12');
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('Password123!');
    cy.get('[data-testid="login-button"]').click();
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Login successful');
    cy.get('[data-testid="login-form"]').should('not.exist');
  });
});
